from taf.cloud.cbam.schemas.schema_base import CbamSchema


class ProblemDetails(CbamSchema):
    def __init__(self, detail, status, title=None, problem_type=None, instance=None):
        self.detail = detail
        self.status = status
        self.title = title
        self.problem_type = problem_type
        self.instance = instance

    @classmethod
    def from_response_dict(cls, resp_dict):
        if resp_dict is None:
            resp_dict = {}

        return cls(detail=resp_dict.get('detail', None),
                   status=resp_dict.get('status', None),
                   title=resp_dict.get('title', None),
                   problem_type=resp_dict.get('type', None),
                   instance=resp_dict.get('instance', None))

    def as_dict(self):
        result = {'status': self.status,
                  'detail': self.detail,
                  'title': self.title,
                  'type': self.problem_type,
                  'instance': self.instance}

        result = {k: v for k, v in result.items() if v is not None}
        return result
